let demoClassPermissions=[];try{demoClassPermissions=JSON.parse(localStorage.getItem('homework-class-permissions')||'[]')}catch{}
function teacherPermission(action,classId=activeClassId(),userId=cloud.ready?cloud.user.id:school.teacherId){if(!['can_update_lessons','can_answer_questions','can_publish_class_answers'].includes(action))return false;const rights=(cloud.ready?cloud.permissions:demoClassPermissions).find(p=>p.class_id===classId&&p.user_id===userId);return rights?!!rights[action]:true}
function renderPermissionUsers(){const classId=document.getElementById('permissionClass').value;const assigned=school.teachers.filter(t=>t.classIds.includes(classId));fillAdminSelect(document.getElementById('permissionTeacher'),assigned,'');loadPermissionForm()}
function loadPermissionForm(){const classId=document.getElementById('permissionClass').value,userId=document.getElementById('permissionTeacher').value;for(const [id,action] of [['allowLessons','can_update_lessons'],['allowAnswers','can_answer_questions'],['allowPublicAnswers','can_publish_class_answers']])document.getElementById(id).checked=teacherPermission(action,classId,userId)}
function renderPermissions(){fillAdminSelect(document.getElementById('permissionClass'),school.classes.filter(c=>c.schoolId===activeSchoolId()),activeClassId());renderPermissionUsers()}
document.getElementById('permissionClass').onchange=renderPermissionUsers;document.getElementById('permissionTeacher').onchange=loadPermissionForm;
document.getElementById('saveClassPermissions').onclick=async()=>{const status=document.getElementById('permissionStatus');try{if(!canAdminSchool())throw new Error(t('אין הרשאה לבית הספר.'));const class_id=document.getElementById('permissionClass').value,user_id=document.getElementById('permissionTeacher').value;if(!user_id||!school.classes.some(c=>c.id===class_id&&c.schoolId===activeSchoolId()))throw new Error(t('בחרו מורה וכיתה.'));const row={class_id,user_id,can_update_lessons:document.getElementById('allowLessons').checked,can_answer_questions:document.getElementById('allowAnswers').checked,can_publish_class_answers:document.getElementById('allowPublicAnswers').checked};if(cloud.ready){await cloudResult(cloud.client.from('school_class_permissions').upsert(row,{onConflict:'class_id,user_id'}));await cloudRefresh()}else{demoClassPermissions=demoClassPermissions.filter(p=>p.class_id!==class_id||p.user_id!==user_id);demoClassPermissions.push(row);localStorage.setItem('homework-class-permissions',JSON.stringify(demoClassPermissions));render()}status.textContent=t('ההרשאות נשמרו.')}catch(e){status.textContent=e.message}};
renderPermissions();
